export function ProfileEditor({saved,onSaved,onDismiss}:{saved:Profile;onSaved:(profile:Profile)=>void;onDismiss:()=>void}){const [draft,setDraft]=useState<Profile>(()=>({...saved}));const [tab,setTab]=useState<"data"|"notifications"|"security">("data");const [file,setFile]=useState<File|null>(null);const [preview,setPreview]=useState<string|null>(null);const [errors,setErrors]=useState<Errors>({});const [confirm,setConfirm]=useState(false);const [pending,setPending]=useState(false);const [saveError,setSaveError]=useState<string|null>(null);const [securityStatus,setSecurityStatus]=useState("");const email=useRef<EmailHandle>(null);const nameInput=useRef<HTMLInputElement>(null);const bioInput=useRef<HTMLTextAreaElement>(null);const fileInput=useRef<HTMLInputElement>(null);const returnButton=useRef<HTMLButtonElement>(null);const saveButton=useRef<HTMLButtonElement>(null);const wanted=useRef<keyof Errors|null>(null);const returnToSave=useRef(false);const timer=useRef<ReturnType<typeof setTimeout>|null>(null);const saving=useRef(false);const confirmationPopover=useRef<HTMLDivElement>(null);const securityButton=useRef<HTMLButtonElement>(null);const popoverId=useId();const confirmId=useId();const nameId=useId();const bioId=useId();const fileId=useId();const dirty=isDirty(saved,draft,file);useEffect(()=>{if(!file){setPreview(null);return;}const url=URL.createObjectURL(file);setPreview(url);return ()=>URL.revokeObjectURL(url);},[file]);useEffect(()=>()=>{if(timer.current!==null)clearTimeout(timer.current);},[]);useEffect(()=>{if(tab!=="security")confirmationPopover.current?.hidePopover();},[tab]);useLayoutEffect(()=>{if(returnToSave.current){returnToSave.current=false;saveButton.current?.focus();}const field=wanted.current;if(!field)return;wanted.current=null;if(field==="email")email.current?.attention();else if(field==="name")nameInput.current?.focus();else if(field==="bio")bioInput.current?.focus();else fileInput.current?.focus();});useLayoutEffect(()=>{if(confirm)returnButton.current?.focus();},[confirm]);function patch<K extends keyof Profile>(key:K,value:Profile[K]){setDraft(current=>({...current,[key]:value}));}function requestClose(){if(saving.current)return;if(dirty)setConfirm(true);else onDismiss();}function chooseFile(next:File|null){if(saving.current)return;const problem=avatarError(next);if(problem){setErrors(current=>({...current,avatar:problem}));return;}setFile(next);setErrors(current=>({...current,avatar:undefined}));}function submit(){if(saving.current)return;const nextErrors=validate(draft);const problem=avatarError(file);if(problem)nextErrors.avatar=problem;setErrors(nextErrors);setSaveError(null);const first=(Object.keys(nextErrors) as (keyof Errors)[])[0];if(first){setTab("data");wanted.current=first;return;}const next=payload(draft,file);saving.current=true;setPending(true);timer.current=setTimeout(()=>{timer.current=null;try{onSaved(next);}catch{saving.current=false;setPending(false);setSaveError("Nie udało się zapisać profilu. Dane pozostają w formularzu.");}},800);}const data=<section><label htmlFor={nameId}>Imię i nazwisko<input id={nameId} data-initial-focus ref={nameInput} value={draft.name} onChange={event=>patch("name",event.currentTarget.value)} aria-invalid={Boolean(errors.name)} aria-describedby={errors.name?nameId+"-error":undefined}/>{errors.name&&<span id={nameId+"-error"}>{errors.name}</span>}</label><EmailField ref={email} value={draft.email} onChange={value=>patch("email",value)} error={errors.email}/><label htmlFor={bioId}>Opis<textarea id={bioId} ref={bioInput} value={draft.bio} onChange={event=>patch("bio",event.currentTarget.value)} aria-invalid={Boolean(errors.bio)} aria-describedby={bioId+"-count"+(errors.bio?" "+bioId+"-error":"")}/></label><p id={bioId+"-count"}>{draft.bio.length}/160 jednostek UTF-16</p>{errors.bio&&<p id={bioId+"-error"}>{errors.bio}</p>}<label htmlFor={fileId}>Awatar PNG/JPEG do 2 MiB<input id={fileId} ref={fileInput} type="file" accept="image/png,image/jpeg" onChange={event=>{const next=event.currentTarget.files?.[0]??null;chooseFile(next);event.currentTarget.value="";}} aria-invalid={Boolean(errors.avatar)} aria-describedby={errors.avatar?fileId+"-error":undefined}/></label>{errors.avatar&&<p id={fileId+"-error"}>{errors.avatar}</p>}{preview&&<img src={preview} alt="Podgląd wybranego awatara" width={96} height={96}/>}<p>Wybrany plik: {(file?.name??draft.avatarName)||"brak"}</p>{file&&<button type="button" onClick={()=>chooseFile(null)}>Anuluj wybór pliku</button>}</section>;const notifications=<section><label><input type="checkbox" checked={draft.emailAlerts} onChange={event=>patch("emailAlerts",event.currentTarget.checked)}/>E-mail</label><label><input type="checkbox" checked={draft.inApp} onChange={event=>patch("inApp",event.currentTarget.checked)}/>W aplikacji</label><label><input type="checkbox" checked={draft.sound} onChange={event=>patch("sound",event.currentTarget.checked)}/>Dźwięk</label><label>Częstotliwość<select value={draft.frequency} onChange={event=>{const value=event.currentTarget.value;if(value==="daily"||value==="weekly"||value==="never")patch("frequency",value);}}><option value="daily">Codziennie</option><option value="weekly">Co tydzień</option><option value="never">Nigdy</option></select></label></section>;const security=<section><p>Symulacja lokalna — przycisk nie wylogowuje rzeczywistych sesji.</p><button ref={securityButton} type="button" popoverTarget={popoverId}>Wyloguj ze wszystkich urządzeń</button><div ref={confirmationPopover} id={popoverId} popover="auto"><p>Potwierdzić symulowane wylogowanie?</p><button type="button" onClick={()=>{setSecurityStatus("Symulacja zakończona: pozostałe sesje wylogowane.");confirmationPopover.current?.hidePopover();securityButton.current?.focus();}}>Potwierdź</button><button type="button" popoverTarget={popoverId} popoverTargetAction="hide">Anuluj</button></div><p role="status">{securityStatus}</p></section>;return <NativeModal open title="Edytuj profil" onClose={requestClose}><p>Zapis jest symulowany przez 800 ms. Zapisywana jest nazwa pliku; przykład nie wysyła awatara na serwer.</p><form noValidate aria-busy={pending} onSubmit={event=>{event.preventDefault();submit();}}><fieldset disabled={pending||confirm}><legend>Ustawienia profilu</legend><Tabs<"data"|"notifications"|"security"> label="Ustawienia" value={tab} onChange={setTab} tabs={[{id:"data",label:"Dane",content:data},{id:"notifications",label:"Powiadomienia",content:notifications},{id:"security",label:"Bezpieczeństwo",content:security}]}/><button ref={saveButton} type="submit">{pending?"Zapisywanie…":"Zapisz"}</button><button type="button" onClick={requestClose}>Anuluj</button></fieldset></form>{saveError&&<p role="alert">{saveError}</p>}{confirm&&<section role="group" aria-labelledby={confirmId}><h2 id={confirmId}>Masz niezapisane zmiany</h2><button type="button" onClick={onDismiss}>Odrzuć</button><button ref={returnButton} type="button" onClick={()=>{returnToSave.current=true;setConfirm(false);}}>Wróć do edycji</button></section>}</NativeModal>;}

